'use client'

import type { ComponentProps } from 'react'
import { ToggleGroup as BaseToggleGroup } from '@base-ui/react/toggle-group'
import { cn } from '@/lib/utils'
import styles from './ButtonGroup.module.css'

export type ButtonGroupProps = ComponentProps<'div'>

/** Buttons joined into one bar: related actions that read as a set. */
export function ButtonGroup({ className, ...props }: ButtonGroupProps) {
  return <div role="group" {...props} className={cn(styles.group, className)} />
}

export interface ToggleGroupProps
  extends Omit<ComponentProps<'div'>, 'defaultValue' | 'onChange' | 'dir'> {
  /** Controlled: the `value` of each pressed ToggleButton. */
  value?: string[]
  /** Uncontrolled: the values pressed at first. */
  defaultValue?: string[]
  /** Base UI's second argument (event details) is dropped: nothing here needs it. */
  onValueChange?: (value: string[]) => void
  /** Any number pressed at once. Without it, one at a time: a segmented control. */
  multiple?: boolean
  /** Disables every toggle in the group. */
  disabled?: boolean
}

/** ToggleButtons joined into one bar, sharing one selection. */
export function ToggleGroup({ onValueChange, multiple = false, className, ...props }: ToggleGroupProps) {
  return (
    <BaseToggleGroup
      {...props}
      multiple={multiple}
      onValueChange={(next, details) => {
        // Single choice is a segmented control: once a segment is chosen,
        // pressing it again does not leave none chosen.
        if (!multiple && next.length === 0) return details.cancel()
        onValueChange?.(next)
      }}
      className={cn(styles.group, className)}
    />
  )
}

/* The buttons keep their own size and colour; the group only joins them.
   Inner corners go square and each button after the first overlaps the
   previous one by its 1px border, so two outlined buttons share one line
   instead of drawing a double one. Two classes' worth of specificity, so
   it outranks Button's size class whichever stylesheet loads first. */
.group {
  display: inline-flex;
  /* Keeps the z-index below inside the group. */
  isolation: isolate;
}

.group > :not(:first-child) {
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- the buttons' 1px border, see above */
  margin-inline-start: -1px;
  border-start-start-radius: 0;
  border-end-start-radius: 0;
}

.group > :not(:last-child) {
  border-start-end-radius: 0;
  border-end-end-radius: 0;
}

/* A pressed button's border is its own colour; raised, it draws over the
   neighbour's line it overlaps. Focus goes higher still so the ring is
   never cut by the next button. */
.group > [aria-pressed='true'] {
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- local stacking inside the group, not a global layer */
  z-index: 1;
}

/* A contained button's hover ring stands off the button, so in a group it
   would cut across the next button. The hover fill is enough to show which
   one the pointer is on. Doubled class to outrank Button's hover rule. */
.group.group > :hover:not(:focus-visible) {
  outline: none;
}

.group > :focus-visible {
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- local stacking inside the group, not a global layer */
  z-index: 2;
}
